head.script:
// 테스트 설명, 유효성 값 설정
//  [분리 사유] @spec2(RowNum, RowStatus Header 속성 설정 불가) 와 @spec3(Body MultiLine) 은
//   검증에 필요한 GridView 구성이 서로 다르다.
//    - @spec2 : RowNum / RowStatus Column 을 표시한 단일 Line 그리드
//    - @spec3 : Body 가 2 Line 으로 나뉜 MultiLine 그리드
//   한 샘플에 두 구성을 함께 두면 전제가 섞여 관찰 대상이 모호해지므로 _3(@spec2) / _4(@spec3) 로 분리한다.
//  [소유 범위] 본 샘플은 @spec2 만 검증한다.
//   기본 propval(true / false) 과 'Header Column 에서만 동작' 은 _1,
//   headerFilter / useFilterList / showSortableUseFilter 상호작용은 _2 가 소유하므로 여기서 중복 검증하지 않는다.
scwin.tData = {
    "description" : "[column > P > useFilter]<br/>GridView 컴포넌트의 Header Column 에 CustomFilter 기능을 활성화할지 설정합니다.",
    "validation" : [
        "RowNum, RowStatus Column 의 Header 에는 useFilter 속성을 포함하여 모든 속성을 설정할 수 없습니다.",
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// Header 필터 버튼 표시 확인 :
//  RowNum / RowStatus Header 와, useFilter=true 로 설정된 일반 Header Column 의 필터 버튼(input.w2grid_customFilter_open)
//  표시 여부를 대비 출력한다.
//  (RowNum / RowStatus Header 는 rowNumVisible / rowStatusVisible 로만 생성되어 Column 선언 자체가 없으므로
//   useFilter 를 포함한 어떤 Header Column 속성도 반영되지 않는다.)
scwin.btn_checkFilterButton_onclick = function () {
    let scb = wf_body_bottom.getObj("scwin");
    scb.btn_clear_onclick();

    let rowNumTh = document.querySelector("th[id$='_headerRowNumber']");
    let rowStatusTh = document.querySelector("th[id$='_headerRowStatus']");
    let rowNumFilter = rowNumTh ? !!rowNumTh.querySelector("input.w2grid_customFilter_open") : "Header 미표시";
    let rowStatusFilter = rowStatusTh ? !!rowStatusTh.querySelector("input.w2grid_customFilter_open") : "Header 미표시";
    scb.setReturnValue("RowNum Header 필터 버튼 : " + rowNumFilter + " / RowStatus Header 필터 버튼 : " + rowStatusFilter);

    // 대조군 : useFilter=true 를 설정할 수 있는 일반 Header Column
    let column1Th = document.querySelector("th[id$='_column1']");
    let column1Filter = column1Th ? !!column1Th.querySelector("input.w2grid_customFilter_open") : "Header 미표시";
    scb.setReturnValue("[대조] 일반 Header Column(column1, useFilter=true) 필터 버튼 : " + column1Filter);
}
